create or replace function public.lookup_payee_account(p_account_number text) returns table(id uuid,name text,account_number text) language plpgsql stable security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; return query select a.id,a.name,a.account_number from public.bank_accounts a where a.account_number=upper(trim(p_account_number)) and a.status='active' and a.kind<>'treasury' limit 1; end $$; revoke all on function public.lookup_payee_account(text) from public,anon,authenticated; grant execute on function public.lookup_payee_account(text) to authenticated;